$deadline = (Get-Date).AddSeconds(15); while ((Get-Date) -lt $deadline) { try { $taskInfo = Get-ScheduledTask -TaskName {{task}} -ErrorAction Stop } catch { if ($_.FullyQualifiedErrorId -like 'CmdletizationQuery_NotFound_TaskName*') { exit 0 }; Write-Error $_; exit 1 }; if ($taskInfo.State -ne 'Running') { exit 0 }; Start-Sleep -Milliseconds 100 }; Write-Error 'scheduled task did not stop within 15 seconds'; exit 1